package eu.simplexsmp.adminsuite;

import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.bukkit.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.scheduler.BukkitTask;

/** Optional, unified Java/Floodgate administration with durable, private Discord delivery. */
final class ClientControlCenter implements Listener {
    static final String ROOT="client-control.";
    final SimplexAdminSuite plugin;final ClientAccessOverrides overrides;final ProbeRelocation relocation;final RestartPlanner calendar;final GeoInsights geo;
    private final AltAlertLedger ledger;private final SecurityLogOutbox outbox;private final Set<UUID> baseline;
    private final ClientEventWindow clients=new ClientEventWindow(900000),joins=new ClientEventWindow(10000);
    private final Path clientWindowsFile,joinWindowsFile;
    private final Map<UUID,LinkedHashMap<String,String>> packs=new HashMap<>();private final Path packsFile;
    private final Map<UUID,Long> emergenciesSeen=new HashMap<>();private volatile boolean geoEnabled;private volatile Set<String> allowedChannels=Set.of();private boolean seeding;private volatile boolean closing;private BukkitTask timer;private long lastError;
    ClientControlCenter(SimplexAdminSuite p)throws IOException{plugin=p;Path folder=p.getDataFolder().toPath();baseline=p.securityProfileIds();clientWindowsFile=folder.resolve("client-log-windows.properties");joinWindowsFile=folder.resolve("join-log-windows.properties");clients.restore(clientWindowsFile);joins.restore(joinWindowsFile);overrides=new ClientAccessOverrides(folder.resolve("client-access-overrides.properties"));relocation=new ProbeRelocation(p);calendar=new RestartPlanner(p);ledger=new AltAlertLedger(folder.resolve("alt-alert-ledger.properties"));packsFile=folder.resolve("server-pack-observations.properties");
        if(Files.exists(packsFile)){Properties values=new Properties();try(Reader in=Files.newBufferedReader(packsFile)){values.load(in);}for(String key:values.stringPropertyNames()){String[] parts=key.split("/",2);if(parts.length==2)packs.computeIfAbsent(UUID.fromString(parts[0]),k->new LinkedHashMap<>()).put(parts[1],values.getProperty(key));}}
        geo=new GeoInsights(folder.resolve("geo-insights.properties"),()->geoEnabled,this::error);
        try{outbox=new SecurityLogOutbox(folder.resolve("security-log-outbox.db"),m->{DiscordBotManager bot=p.discordRelay();return allowedChannels.contains(m.channel())&&bot!=null&&bot.sendSecurityDossier(m);},this::error,c->allowedChannels.contains(c));}catch(java.sql.SQLException e){geo.close();throw new IOException("Discord outbox unavailable; state preserved",e);}reload();
    }
    Map<String,Object> logStatus(){Map<String,Object> data=new LinkedHashMap<>(outbox.status());data.put("enabledChannels",allowedChannels.size());DiscordBotManager bot=plugin.discordRelay();data.put("discord",bot==null?"Bot nicht gestartet":bot.privateDossierStatus());return data;}
    void retryLogs(){outbox.retry();}
    void start(){plugin.bindEmergencyProfiles();Bukkit.getPluginManager().registerEvents(this,plugin);Bukkit.getPluginManager().registerEvents(relocation,plugin);relocation.restoreOnline();calendar.start();timer=Bukkit.getScheduler().runTaskTimer(plugin,this::tick,20,20);seed();}
    void reload(){geoEnabled=plugin.getConfig().getBoolean(ROOT+"geo.enabled",false);Set<String> allowed=new HashSet<>();for(String type:List.of("client-probes","join-details","alt-accounts")){String key=type.equals("client-probes")?"client-log.enabled":type.equals("join-details")?"join-log.enabled":"alt-alerts.enabled";if(plugin.getConfig().getBoolean(ROOT+key,type.equals("client-probes"))&&configured(type))allowed.add(channel(type));}allowedChannels=Set.copyOf(allowed);}
    void stop(){closing=true;if(timer!=null)timer.cancel();calendar.stop();if(plugin.qualityOfLife!=null)for(Player p:Bukkit.getOnlinePlayers())plugin.qualityOfLife.probes.interrupt(p);relocation.restoreOnline();checkpoint();outbox.close();geo.close();}
    private void error(String text){long now=System.currentTimeMillis();synchronized(this){if(now-lastError<60000)return;lastError=now;}plugin.getLogger().warning(text);}
    private String channel(String type){return plugin.getConfig().getString("discord-bot.moderation-log."+type+"-channel-id","");}
    private boolean configured(String type){return channel(type).matches("[0-9]{15,22}");}
    private void seed(){if(ledger.seeded||seeding)return;seeding=true;plugin.securityGroups(groups->{Map<UUID,Set<UUID>> old=new LinkedHashMap<>();groups.forEach((root,members)->{Set<UUID> known=new HashSet<>(members);known.retainAll(baseline);if(known.size()>1)old.put(anchor(known),known);});try{ledger.seed(old);}catch(IOException e){error("Alt-Alert-Basis konnte nicht gespeichert werden");}finally{seeding=false;}});}
    private UUID anchor(Set<UUID> ids){return ids.stream().min(Comparator.comparingLong(id->{Object at=plugin.securityDossier(id,false,false).get("firstSeen");return at instanceof Number n?n.longValue():Long.MAX_VALUE;})).orElseThrow();}
    private void checkpoint(){try{clients.checkpoint(clientWindowsFile);joins.checkpoint(joinWindowsFile);}catch(IOException e){error("Protokoll-Sammelfenster konnten nicht gespeichert werden");}}
    private void tick(){reload();long now=System.currentTimeMillis();if(plugin.getConfig().getBoolean(ROOT+"client-log.enabled",true)&&configured("client-probes"))for(var d:clients.flush(now))if(!deliver("client-probes",d))clients.requeue(d,now);if(plugin.getConfig().getBoolean(ROOT+"join-log.enabled",false)&&configured("join-details"))for(var d:joins.flush(now))if(!deliver("join-details",d))joins.requeue(d,now);checkpoint();
        for(Player p:Bukkit.getOnlinePlayers()){long expiry=overrides.emergencyUntil(p.getUniqueId());Long before=emergenciesSeen.put(p.getUniqueId(),expiry>now?expiry:0L);if(before!=null&&before>0&&expiry<=now){emergenciesSeen.put(p.getUniqueId(),0L);if(plugin.moderationControl!=null)plugin.moderationControl.refreshOnline();p.sendMessage(plugin.playerText(p,"§eDer temporäre Notfallzugang ist abgelaufen.","§eYour temporary emergency access has expired."));}}
        emergenciesSeen.keySet().removeIf(id->Bukkit.getPlayer(id)==null);if(!ledger.seeded)seed();
    }
    void joined(Player p){UUID id=p.getUniqueId();Bukkit.getScheduler().runTaskLater(plugin,()->{if(Bukkit.getPlayer(id)!=p)return;
        if(geoEnabled&&p.getAddress()!=null){String ip=p.getAddress().getAddress().getHostAddress();geo.enqueue(plugin.geoIpKey(ip),ip);}
        if(plugin.getConfig().getBoolean(ROOT+"join-log.enabled",false)&&configured("join-details"))offer("join-details",joins,id,p.getName(),"Beitritt • "+(plugin.isBedrockClient(p)?"Bedrock":"Java"),"Serverbeitritt; Details im JSON-Anhang.");alt(id);
    },40L);}
    @EventHandler(priority=EventPriority.MONITOR)public void loginAttempt(AsyncPlayerPreLoginEvent e){if(closing)return;if(e.getLoginResult()==AsyncPlayerPreLoginEvent.Result.ALLOWED)return;UUID id=e.getUniqueId();String name=e.getName(),reason=e.getLoginResult().name();Bukkit.getScheduler().runTask(plugin,()->{if(plugin.getConfig().getBoolean(ROOT+"join-log.enabled",false)&&configured("join-details"))offer("join-details",joins,id,name,"Abgewiesener Verbindungsversuch",reason+" • Vorherige gespeicherte Metadaten; neue Client-Details sind vor Login nicht verfügbar.");if(plugin.qualityOfLife!=null&&ClientProbeAccess.restricted(plugin.qualityOfLife.probes.access.state(id),System.currentTimeMillis()))clientMessage(id,name,"Client-Zugang gesperrt",reason);});}
    @EventHandler(priority=EventPriority.MONITOR)public void loginDenied(PlayerLoginEvent e){if(e.getResult()==PlayerLoginEvent.Result.ALLOWED)return;UUID id=e.getPlayer().getUniqueId();String name=e.getPlayer().getName(),reason=e.getResult().name();if(plugin.getConfig().getBoolean(ROOT+"join-log.enabled",false)&&configured("join-details"))offer("join-details",joins,id,name,"Abgewiesener Beitritt",reason);if(configured("client-probes")&&plugin.qualityOfLife!=null&&ClientProbeAccess.restricted(plugin.qualityOfLife.probes.access.state(id),System.currentTimeMillis()))clientMessage(id,name,"Client-Zugang gesperrt",reason);}
    void hint(Player p,String check,String title,String detail,boolean behavior){boolean kick=plugin.getConfig().getBoolean(SecurityDetectors.ROOT+check+".kick",false)&&!plugin.clientExempt(p.getUniqueId(),check)&&!plugin.emergency(p.getUniqueId());String action=kick?"KICK":"Hinweis ohne Sanktion";
        if(plugin.getConfig().getBoolean(ROOT+"client-log.enabled",true))clientMessage(p.getUniqueId(),p.getName(),title,detail+"\nMaßnahme: "+action);
        if(kick)plugin.suiteKick(p,plugin.playerText(p,behavior?"§cUngewöhnliches Client-Verhalten erkannt.\nBitte melde dich beim Serverteam.":"§cUngewöhnlicher Client erkannt.\nBitte melde dich beim Serverteam.",behavior?"§cUnusual client behavior detected.\nPlease contact server staff.":"§cUnusual client detected.\nPlease contact server staff."));
    }
    void clientMessage(UUID id,String name,String title,String detail){if(plugin.getConfig().getBoolean(ROOT+"client-log.enabled",true)&&configured("client-probes"))offer("client-probes",clients,id,name,title,detail);}
    private void offer(String type,ClientEventWindow window,UUID id,String name,String title,String detail){Map<String,Object> dossier=dossier(id);dossier.put("event",Map.of("title",title,"detail",detail));ClientEventWindow.Delivery delivery=window.offer(new ClientEventWindow.Event(id,name,title,detail,DiscordBotManager.Json.stringify(dossier),System.currentTimeMillis()));if(delivery!=null&&!deliver(type,delivery))window.requeue(delivery,System.currentTimeMillis());checkpoint();}
    private Map<String,Object> dossier(UUID id){Map<String,Object> values=new LinkedHashMap<>(plugin.securityDossier(id,plugin.getConfig().getBoolean(ROOT+"privacy.full-ip",false),plugin.getConfig().getBoolean(ROOT+"join-log.include-checks",true)));values.put("serverPackStatuses",new LinkedHashMap<>(packs.getOrDefault(id,new LinkedHashMap<>())));GeoInsights.Result result=geo.get(plugin.profileIpKey(id));if(result!=null)values.put("approximateIpLocation",Map.of("at",result.at(),"country",result.country(),"region",result.region(),"city",result.city(),"postal",result.postal(),"provider",result.isp(),"timezone",result.timezone(),"identityEvidence",false));return values;}
    private boolean deliver(String type,ClientEventWindow.Delivery d){var e=d.latest();String body="Spieler: "+e.name()+" (`"+e.player()+"`)\nEreignisse: "+d.count()+"\n"+d.kinds()+"\n\n"+SecuritySignals.safe(e.detail())+searchLines(e.dossier())+"\n\nVollständige verfügbare Daten im JSON-Anhang. Angaben sind Hinweise, keine sicheren Identitätsnachweise.";if(!configured(type))return false;boolean queued=outbox.enqueue(new SecurityLogOutbox.Message(channel(type),e.title()+(d.count()>1?" • gesammelt":""),body,e.dossier()));return queued;}
    private String searchLines(String json){try{Map<?,?> d=(Map<?,?>)DiscordBotManager.Json.parse(json);StringBuilder s=new StringBuilder("\nPlattform: "+d.get("platform")+" • IP: "+d.getOrDefault("ip",null)+" • maskiert: "+d.get("ipMasked")+"\nIP-Pseudonym: "+d.get("ipPseudonym"));if(d.get("java") instanceof Map<?,?> m)s.append("\nJava: ").append(m.get("brand")).append(" • Protokoll: ").append(m.get("protocol")).append(" • Locale: ").append(m.get("locale"));if(d.get("bedrock") instanceof Map<?,?> m)s.append("\nBedrock: ").append(m.get("model")).append(" / ").append(m.get("os")).append(" / ").append(m.get("language")).append("\nGerät-Pseudonym: ").append(m.get("deviceIdPseudonym")).append("\nXUID-Pseudonym: ").append(m.get("xuidPseudonym"));return s.toString();}catch(RuntimeException invalid){return "";}}
    private void alt(UUID joining){if(!plugin.getConfig().getBoolean(ROOT+"alt-alerts.enabled",false)||!configured("alt-accounts"))return;if(!ledger.seeded){seed();Bukkit.getScheduler().runTaskLater(plugin,()->alt(joining),40);return;}
        plugin.securityGroups(groups->{Set<UUID> members=groups.values().stream().filter(v->v.contains(joining)&&v.size()>1).findFirst().orElse(null);if(members==null)return;try{AltAlertLedger.Alert alert=ledger.observe(joining,anchor(members),members);if(alert==null)return;List<String> known=alert.known().stream().map(id->plugin.discordAdminPlayerName(id)+" (`"+id+"`)").sorted().toList();String detail="Neuer möglicher Alt: "+plugin.discordAdminPlayerName(joining)+"\nReferenzaccount: "+plugin.discordAdminPlayerName(alert.anchor())+"\nBekannte Konten:\n"+String.join("\n",known)+"\nStarke Gruppenrelation (Geräte-/XUID-/authentifizierte oder manuelle Verknüpfung). Geteilte Geräte sind möglich; keine neue automatische Sperre.";Map<String,Object> data=dossier(joining);data.put("accountGroup",Map.of("reference",alert.anchor().toString(),"joining",joining.toString(),"related",members.stream().map(UUID::toString).sorted().toList()));
            if(outbox.enqueue(new SecurityLogOutbox.Message(channel("alt-accounts"),"Neuer Alt-Account-Hinweis",detail,DiscordBotManager.Json.stringify(data))))ledger.acknowledged(alert);else error("Alt-Hinweis wartet auf freie Protokollwarteschlange");
        }catch(IOException e){error("Alt-Alert-Zustand konnte nicht gespeichert werden");}});
    }
    @EventHandler(priority=EventPriority.MONITOR)public void pack(PlayerResourcePackStatusEvent e){if(!plugin.getConfig().getBoolean(ROOT+"server-pack-status.enabled",false)||plugin.isBedrockClient(e.getPlayer()))return;LinkedHashMap<String,String> values=packs.computeIfAbsent(e.getPlayer().getUniqueId(),k->new LinkedHashMap<>());String id=e.getID().toString();values.remove(id);values.put(id,e.getStatus().name()+" @ "+Instant.now());while(values.size()>32)values.remove(values.keySet().iterator().next());Properties state=new Properties();packs.forEach((uuid,entries)->entries.forEach((key,value)->state.setProperty(uuid+"/"+key,value)));try{AtomicState.save(packsFile,state,"Client-reported server pack statuses; no local pack inventory or device identity");}catch(IOException error){error("Paketstatus konnte nicht gespeichert werden");}}
    private boolean admin(Player p){return plugin.has(p,"simplexadminsuite.clientsecurity.admin")&&plugin.adminSessionUsable(p);}
    private AdminUpdateMenu.Button button(Player p,String title,String detail,Material icon,Runnable action){return new AdminUpdateMenu.Button(title,detail,icon,()->{if(admin(p))action.run();});}
    private void toggle(Player p,List<AdminUpdateMenu.Button> items,String title,String key){boolean on=plugin.getConfig().getBoolean(key,false);items.add(button(p,title,on?"An • ausschalten":"Aus • einschalten",on?Material.LIME_DYE:Material.GRAY_DYE,()->{plugin.getConfig().set(key,!on);plugin.saveConfig();reload();menu(p);}));}
    void menu(Player p){if(!admin(p))return;List<AdminUpdateMenu.Button> items=new ArrayList<>();items.add(AdminUpdateMenu.info("Client-Protokolle & Ausnahmen","Erster Client-Hinweis sofort; weitere 15 Minuten sammeln. Beitrittsdaten höchstens alle 10 Sekunden je UUID. Neue Alt-Konten einmal pro Gruppe. Versandwarteschlange: "+outbox.pending()+"\nGeräte-IDs pseudonymisiert, keine Hardware-ID für Java.",Material.SHIELD));
        toggle(p,items,"Client-Hinweise im vorhandenen Kanal",ROOT+"client-log.enabled");toggle(p,items,"Neue Alt-Account-Alerts",ROOT+"alt-alerts.enabled");toggle(p,items,"Private Beitrittsdaten",ROOT+"join-log.enabled");toggle(p,items,"Letzte Client-Prüfung im Anhang",ROOT+"join-log.include-checks");toggle(p,items,"Vollständige IP statt maskiert",ROOT+"privacy.full-ip");toggle(p,items,"Serverpaket-Status beobachten",ROOT+"server-pack-status.enabled");toggle(p,items,"Ungefähre IP-Standortdiagnose",ROOT+"geo.enabled");toggle(p,items,"Himmel-Ausweichprüfung bei Platzmangel",ClientProbeRules.ROOT+"sky-fallback");toggle(p,items,"Experimentell: kürzere Prüfpausen",ClientProbeRules.ROOT+"experimental-fast");
        items.add(button(p,"Spieler, Daten & Prüf-Whitelist","Ganzes Profil oder einzelne Prüf-IDs von Sanktionen ausnehmen",Material.PLAYER_HEAD,()->players(p)));
        items.add(button(p,"Discord-Kanäle einrichten","Bestehenden privaten Kanal wählen oder vom Bot erstellen lassen",Material.HOPPER,()->plugin.moderationControl.discord(p)));
        items.add(button(p,"Wartende Discord-Protokolle löschen","Nur neue Versandwarteschlange; bestehende Profile und Sperren bleiben erhalten",Material.BARRIER,()->plugin.adminUpdate.prompt(p,"Zum Löschen LÖSCHEN eingeben","",value->{if(!admin(p))return;if(value.equals("LÖSCHEN")&&outbox.clear())plugin.menuNotice(p,"§aWartende Versanddaten gelöscht.");menu(p);})));
        items.add(button(p,"Frühere verfügbare IPs analysieren","1 Profil/Sekunde; nur echte IPs. Hashes können nicht zurückgerechnet werden. Max. 900 HTTPS-Anfragen pro 24 Stunden, gemeinsame Warteschlange: "+geo.pending(),Material.COMPASS,()->{if(geoEnabled)plugin.historicalGeo(geo::enqueue);else plugin.menuError(p,"§eStandortdiagnose zuerst einschalten.");menu(p);}));
        if(plugin.has(p,"simplexadminsuite.operations"))items.add(button(p,"Neustarts nach deutscher Uhrzeit","Europe/Berlin, Countdown und Zeitzone",Material.CLOCK,()->calendar.menu(p)));
        items.add(button(p,"Notfallzugang über die Konsole","/sas emergency <Spieler> on|off|status\n30 Minuten, Sperren bleiben gespeichert. Keine Freigabe fremder Plugins/Whitelist/Authentifizierung.",Material.TRIPWIRE_HOOK,()->plugin.menuNotice(p,"§eNur Konsole: /sas emergency <Spieler> on|off|status")));
        items.add(button(p,"Zurück","Sicherheit",Material.OAK_DOOR,()->plugin.unifiedMenu.category(p,"Sicherheit")));plugin.adminUpdate.show(p,"Sicherheitszentrale 8.1",items,0);
    }
    private void players(Player p){if(!admin(p))return;List<AdminUpdateMenu.Button> items=new ArrayList<>();plugin.securityProfileIds().stream().sorted(Comparator.comparing(plugin::discordAdminPlayerName,String.CASE_INSENSITIVE_ORDER)).forEach(id->items.add(button(p,plugin.discordAdminPlayerName(id),"Whitelist: "+overrides.whitelist(id),Material.PLAYER_HEAD,()->player(p,id))));items.add(button(p,"Zurück","Sicherheitszentrale",Material.OAK_DOOR,()->menu(p)));plugin.adminUpdate.show(p,"Client-Daten & Ausnahmen",items,0);}
    void player(Player p,UUID id){if(!admin(p))return;List<AdminUpdateMenu.Button> items=new ArrayList<>();items.add(AdminUpdateMenu.info(plugin.discordAdminPlayerName(id),"Ausnahmen: "+overrides.whitelist(id)+"\nDiagnosen beeinflussen die Alt-Zuordnung nicht.\n"+geoText(id),Material.NAME_TAG));
        List<String> checks=new ArrayList<>(List.of("all","channel-fingerprint","anti-detection","autoclicker","freecam"));if(plugin.qualityOfLife!=null)checks.addAll(plugin.qualityOfLife.probes.definitionIds());for(String check:checks){boolean on=overrides.whitelist(id).contains(check);items.add(button(p,(check.equals("all")?"Alle Prüf-Sanktionen":check)+(on?" • Ausnahme":""),on?"Ausnahme entfernen":"Von Kick/Bann/Review ausnehmen; Diagnose bleibt",on?Material.LIME_DYE:Material.GRAY_DYE,()->{try{overrides.whitelist(id,check,!on);plugin.expansionAudit(p.getName(),id,"Client-Sanktionsausnahme",check+"="+!on);}catch(IOException e){plugin.menuError(p,"§cAusnahme konnte nicht gespeichert werden.");}player(p,id);}));}
        items.add(button(p,"Client-Daten anzeigen","Beobachtete Metadaten, Serverpaket-Status und letzte Prüfung",Material.WRITABLE_BOOK,()->data(p,id)));Player target=Bukkit.getPlayer(id);if(target!=null&&!plugin.isBedrockClient(target)&&plugin.has(p,"simplexadminsuite.clientcheck"))items.add(button(p,"Client oder einzelne Mod prüfen","Nur Java",Material.SPYGLASS,()->plugin.openClientProbe(p,id)));items.add(button(p,"Zurück","Spielerliste",Material.OAK_DOOR,()->players(p)));plugin.adminUpdate.show(p,"Prüf-Whitelist • "+plugin.discordAdminPlayerName(id),items,0);
    }
    private void data(Player p,UUID id){List<AdminUpdateMenu.Button> items=new ArrayList<>();dossier(id).forEach((key,value)->items.add(AdminUpdateMenu.info(key,Objects.toString(value),Material.PAPER)));items.add(button(p,"Zurück","Profil",Material.OAK_DOOR,()->player(p,id)));plugin.adminUpdate.show(p,"Beobachtete Client-Daten",items,0);}
    private String geoText(UUID id){GeoInsights.Result r=geo.get(plugin.profileIpKey(id));return r==null?"Kein IP-Standort gespeichert":"Ungefährer IP-Standort: "+r.country()+" / "+r.region()+" / "+r.city()+" / "+r.postal()+" • "+r.isp()+"\nNicht verlässlich genug für eine Personen-/Stadtsperre.";}
    boolean command(CommandSender sender,String root,String[] args){if(root.equals("emergency")){
        if(!(sender instanceof ConsoleCommandSender)){sender.sendMessage("Nur direkt in der Serverkonsole verfügbar.");return true;}if(args.length!=2){sender.sendMessage("/sas emergency <Spieler> on|off|status");return true;}UUID id=plugin.discordAdminResolvePlayer(args[0]);if(id==null){sender.sendMessage("Spielerprofil nicht gefunden.");return true;}try{switch(args[1].toLowerCase(Locale.ROOT)){case "on","off"->{boolean on=args[1].equalsIgnoreCase("on");overrides.emergency(id,on,System.currentTimeMillis());emergenciesSeen.put(id,on?overrides.emergencyUntil(id):0L);Player p=Bukkit.getPlayer(id);if(on&&p!=null)plugin.adminRuntime.emergencyRelease(p);if(plugin.moderationControl!=null)plugin.moderationControl.refreshOnline();plugin.expansionAudit("Konsole",id,"Notfallzugang",on?"30 Minuten aktiviert; gespeicherte Sperren unverändert":"Widerrufen");sender.sendMessage(on?"Notfallzugang für 30 Minuten aktiviert. Suite-Sperren bleiben gespeichert; externe Sperren und Weltsicherheitslock gelten weiter.":"Notfallzugang widerrufen; gespeicherte Einschränkungen gelten wieder.");}case "status"->sender.sendMessage("Notfallzugang: "+plugin.emergency(id)+" • Ablauf: "+Instant.ofEpochMilli(overrides.emergencyUntil(id)));default->sender.sendMessage("on, off oder status");}}catch(IOException e){sender.sendMessage("Nicht gespeichert; Zustand wurde nicht geändert.");}return true;
        }
        String permission=root.equals("restartplan")?"simplexadminsuite.operations":"simplexadminsuite.clientsecurity.admin";if(!plugin.has(sender,permission)||sender instanceof Player p&&!plugin.adminSessionUsable(p)){sender.sendMessage("Keine Berechtigung: "+permission);return true;}
        if(root.equals("checkwhitelist")){if(args.length!=3){sender.sendMessage("/sas checkwhitelist <Spieler> <all|Prüf-ID> <on|off>");return true;}UUID id=plugin.discordAdminResolvePlayer(args[0]);if(id==null){sender.sendMessage("Spielerprofil nicht gefunden.");return true;}String check=args[1].toLowerCase(Locale.ROOT);Set<String> known=new HashSet<>(List.of("all","channel-fingerprint","anti-detection","autoclicker","freecam"));known.addAll(plugin.qualityOfLife.probes.definitionIds());if(!known.contains(check)||!Set.of("on","off").contains(args[2])){sender.sendMessage("Unbekannte Prüf-ID oder Aktion; all/on/off verwenden.");return true;}try{overrides.whitelist(id,check,args[2].equals("on"));plugin.expansionAudit(sender.getName(),id,"Client-Sanktionsausnahme",check+"="+args[2]);sender.sendMessage("Prüf-Whitelist gespeichert: "+overrides.whitelist(id));}catch(IOException e){sender.sendMessage("Ausnahme konnte nicht gespeichert werden.");}return true;}
        if(root.equals("geoinfo")){UUID id=args.length==1?plugin.discordAdminResolvePlayer(args[0]):null;sender.sendMessage(id==null?"/sas geoinfo <Spieler>":geoText(id));return true;}
        if(sender instanceof Player p){if(root.equals("restartplan"))calendar.menu(p);else menu(p);}else sender.sendMessage("/sas checkwhitelist … • /sas emergency … • /sas geoinfo … • Menü: /sas securityhub /sas restartplan");return true;
    }
}
